//! Renders the design document's §5.8 from [`crate::rows`].
//!
//! The rendered block sits between [`BEGIN`] and [`END`] in
//! `docs/roadmap/ig2a-governed-semantic-design.md`; `tests/table.rs` fails
//! if the document's block differs, and
//! `cargo run -p kwiry-lifecycle --example lifecycle_table` prints it.

use std::fmt::Write as _;

use crate::rows::{MACHINES, Model};

pub const BEGIN: &str = "<!-- BEGIN GENERATED by daemon/crates/kwiry-lifecycle (cargo run -p kwiry-lifecycle --example lifecycle_table); do not edit by hand -->";
pub const END: &str = "<!-- END GENERATED by daemon/crates/kwiry-lifecycle -->";

const PREAMBLE: &str = r#"**The executable model is normative; this table is derived from it.** The model is `daemon/crates/kwiry-lifecycle`: a pure transition function over the holder's durable store and volatile state, with each of the eleven machines as Rust types, every durable write a separate step, and every step citing the rows below. A bounded model checker interleaves the holder's actors (list apply, report and status senders, transport, GC and purge, release, operator) with an authority that follows the frozen Holdings contract: it reorders, delays, duplicates and loses messages, returns every HW §4.5 error, changes lists, retires rooms and rolls the epoch back through the supported restore. Crashes fall between any two durable writes and keep only durable state. The checker proves the properties listed after the tables in every reachable state, and `cargo test -p kwiry-lifecycle` fails if this table differs from the model's row data. Where the table and the model disagree, the model wins and the table is regenerated.

**Any state and event pair that no row lists is refused:** nothing is written, the state is unchanged, and Kwiry raises `lifecycle_transition_refused` with the machine and row context. Where prose in §4 or §5 disagrees with a row, **the row wins**, and the prose is a defect to fix.

**Notation for durable writes**, listed in fsync order and separated by `→`:

| Symbol | Meaning |
|---|---|
| **W** | Holder-state writer commit: temporary file, fsync, rename, fsync the holder directory (§5.2) |
| **W[x]** | Holder-directory side file `x`, written the same way, before any later W |
| **G** | Generation publication (§4.2 steps 4–5): record, fsync, rename, fsync `generations/`; then `current.json` and fsync the data root |
| **M** | Rollback markers: write `rollback.json` and fsync; unlink `current.v2.json` and fsync the data root |
| **D** | Unlink, then fsync every parent directory |
| **Q** | Rename into `quarantine/<random>/`, fsync both parents, update `quarantine/ledger.json` and fsync |
| **L3** | An in-memory change under L3, with no durability |
| **—** | No write |

In the *Crash after* column, "restart" means startup machine M1 from S1. *Reads* lists the versions, fields and rows each guard depends on. After each machine, *Model* names the rows the model does not execute as a transition of their own, and why."#;

const PROPERTIES: &str = r#"#### Properties the model checker proves

In every reachable state of every bounded run (`daemon/crates/kwiry-lifecycle/src/props.rs`):

| Id | Property |
|---|---|
| I1 | A resource is servable only if the newest list an H row admitted shows it `active` and it is not tombstoned (including A0–A4); neither minting nor any post-retirement list may resurrect a ghost retirement |
| I2 | A unit is deleted only under a listed obligation for its resource, the exact draining release reservation and claimant, or GC of an unreferenced object of an active resource; verify against physical inventory and references |
| I3 | `complete` is never dispatched while the unattributed inventory is non-empty or anything of the resource remains, nor while its proof is stale (the versions R2 recorded moved) |
| I4 | Tombstones only grow |
| I5 | Floors are monotone within an epoch, belong to the high-water's epoch, and evidence minted in another epoch never raises them |
| I6 | Each armed epoch acceptance is consumed at most once |
| I7 | Whenever work is outstanding, some healthy actor (holder, authority, network or operator) can move |
| I8 | An operator wait (auth halt, bug halt) is entered only on an injected fault, never on a correct authority or network response; an `old_instance_stopped` attestation is accepted only after a recorded failed source check no older than 1 h (HW v2 H.48.1; H22) |
| I9 | The unattributed inventory never counts data attributable to a listed holding (units a release reserved excepted) |
| L1 | Liveness: from every reachable state, once crashes, faults and scenario changes stop, every ghost retirement reaches `complete` or human `blocked`, every consumed epoch acceptance is answered by a status accepted in the new epoch (HW §15 H.19), and after an epoch change minting resumes, through member reports (H15) or the lease timeout (H16), including for a member that never reports or never contacts the authority, disabled ones included (H.25, H.30, H.32), and after a raw restore once the old-instance-stopped confirmation exists (HW v2 H.44; without one the authority stays suspected, which is expected non-progress, not a failure), a false attestation included (H.48, H.49); neither absence nor an unheld room without a retirement counts as a lost obligation under strongly fair scheduling of the holder, the healthy authority and network, the human release decision and the operator |

I1 also checks root pins (HW §15 H.16, P1–P8): a served room's pin is non-null and applied (A0 refuses a changed, null or conflicting pin until A4), was minted after any `restore_journal_lost`, is not an orphaned directory, its artifacts hold only its own bytes and were built under its `pin_ref` by the durable derivation record (H.24), and a root mismatch is served only within the H10.5 bound. I1 separately checks holder binding, lease/fence and pinned-key safety, corrupt-journal fencing (HW §15 H.14), the capability window at admission and release (H.15, H.21; C17–C19), a clock hold that takes effect in memory before its durable write, survives restart and only a confirmed correction clears, decided by the inequality alone, and cleared by writing first, so a failed clearing write or a crash after it leaves the hold raised and nothing is answered while holder state records it (H.23, H.26, H.29, H.34; C19–C21), old-ref artifacts that never serve, the stale bound included (H.28; P5), and the epoch-change bound: no holder, the modeled one or two other engine holders of the id-space, releases results from an earlier-epoch list more than 90 s after minting stopped, with frozen membership of every roster holder, disabled ones included, members clearing only by a current-epoch report or the lease timeout and never by a recorded `403`, no override, the journal-lost id-space wait, the journaled roster, an operator epoch that advances every `holder_rev` at `T_stop`, a restore that proceeds only once the old authority is confirmed stopped, a cursor from another epoch refused whatever `holder_rev` says and an epoch-minting transaction of every cause that advances every `holder_rev`, and a raw-restored instance that starts suspected, never confirms by itself and leaves suspicion only through a confirmation by tooling or audited attestation, with `T_stop` the confirmation instant (H.25, H.30–H.33; HW v2 H.41, H.44; H14–H21). After an exit by attestation, a false one included, I1 checks that a holder which applied the exit's key-set statement verifies no list under a retired kid, and that no engine which has cleared the gate answers a capability the old instance minted: the capability key rotation comes before an engine's first new-epoch list (Kwiry's reading of H.49.3). What remains is the named residual, which the false-attestation fixture records: a holder that has not applied the statement, or an engine that has not cleared the gate (HW v2 H.48.3, H.49.3; H22–H24). I8 also checks first-byte cancellation after 403, visibility of eligible release declines, the H.12 validation order, the H.13 proof deadline, the advisory witness rule (H.17), and that a static commit inconsistency cannot write (H.20). Focused fixtures also exercise restored-target replay and custody/status recovery (H.18, H.19). Focused L1 runs prove the H.22 gate release and its durable reading (H.27): with the operator's status resume removed, a retirement still completes after a status bug halt, across a restart too; that the H.29 inequality clears the hold of an engine running ahead on a slow network; and that a later enrollee cannot stall minting (H.30.1). Focused fixtures also check that a restore outlasting the lease timeout resumes minting in its first transaction (H.33.3), that a holder whose `t_r` was lost in a restore is a member (HW v2 H.43), and that list cursors held across a restore and a raw restore with the old instance still running keep the 90 s bound (H.41, H.44). They exercise each cursor control separately: either alone holds without an old-lineage `holder_rev` advance, both removed splice an earlier-epoch page, and within one epoch `holder_rev` alone answers `410` (HW v2 H.47). A lease deadline is fixed at page 0's receipt and never re-anchored by a later step (H.46). The authority never mints a new capability for a ghost retirement, nor after a new epoch before every member has cleared.

The bounds, the reductions and what they leave out are in the crate documentation."#;

const TEST_PLAN: &str = r#"#### Conformance test plan

Every machine is tested by more than one positive test per row. The S3 suite must include each of the following kinds:

| Kind | What it asserts |
|---|---|
| Model check | `cargo test -p kwiry-lifecycle` explores the model exhaustively within its bounds and proves I1–I9 and L1. Each review finding the model reproduced is a regression trace that must violate its property without its fix and hold with it |
| Positive | Each row is exercised at its nominal case **and** at a guard boundary (for example `s == F` and `s == F + 1`; 299 s and 300 s; the last allowed `410`). The next state and writes match the row |
| Negative guard | For each row, every guard conjunct is falsified in turn. The test asserts either the mutually exclusive sibling row (S8/S8n, S9/S9n, S10/S10n, A2/A2n, A3/A3n, R2h/R2x, R2d/R2q, T2h/T2x, T2d/T2q, K2/K2x) or `lifecycle_transition_refused`, with no write |
| Forbidden pair | For each machine, the full state × event matrix is enumerated, and every pair without a row is driven. The test asserts refusal, no durable write, an unchanged state, and the alert |
| Crash at every durability cut | For every row with writes, crashes are injected after each `write`, `fsync`, `rename` and directory `fsync` in its fsync order (including W[x] before W, M's two halves, G's record and pointer, L1's W, G and ledger). The restart outcome must equal the row's *Crash after* column |
| Concurrent startup | Two daemons on one data root; a daemon racing an offline `recover-state`, `accept-epoch`, `resume-report` or `--discard-data-root`; and holder-state appearing between S1L and S4. The test asserts that only the lock holder reads or writes, and that S4's pre-W re-check takes S3 or S5 instead |
| Guard-to-dispatch interleaving | A4 (a withholding, a quarantine move, a release reservation, an obligation change) is injected between R2 and R2h, between R2h and R2d, and likewise for T2, T2h and T2d, both before and after a restart; and a queued attempt is held past 30 s. The test asserts that R2x, R2q, T2x or T2q fires and no stale or expired bytes are transmitted |
| Implementation conformance | The implementation's lifecycle actors are driven by the model's traces (the same action sequences) and must take the same rows |"#;

fn model_note(rows: &[crate::rows::Row]) -> Option<String> {
    let mut groups: Vec<(String, Vec<&str>)> = Vec::new();
    for r in rows {
        let why = match r.model {
            Model::Step => continue,
            Model::Focused(w) => format!("focused CI fixture: {w}"),
            Model::Implicit(w) => format!("implicit: {w}"),
            Model::NotModeled(w) => format!("not modeled: {w}"),
        };
        match groups.iter_mut().find(|(w, _)| *w == why) {
            Some((_, ids)) => ids.push(r.id.name()),
            None => groups.push((why, vec![r.id.name()])),
        }
    }
    if groups.is_empty() {
        return Some("*Model:* every row is a step of the model.".into());
    }
    let parts: Vec<String> = groups
        .iter()
        .map(|(why, ids)| format!("{} ({why})", ids.join(", ")))
        .collect();
    Some(format!(
        "*Model:* every other row is a step of the model. Not a step of its own: {}.",
        parts.join("; ")
    ))
}

/// The generated block, markers included.
pub fn render() -> String {
    let mut out = String::new();
    let _ = writeln!(out, "{BEGIN}\n");
    let _ = writeln!(out, "{PREAMBLE}\n");
    for m in MACHINES {
        let _ = writeln!(out, "#### {} — {}\n", m.key, m.title);
        if !m.intro.is_empty() {
            let _ = writeln!(out, "{}\n", m.intro);
        }
        let _ = writeln!(out, "| {} |", m.header.join(" | "));
        let _ = writeln!(out, "|{}", "---|".repeat(7));
        for r in m.rows {
            let _ = writeln!(out, "| {} | {} |", r.id.name(), r.cells.join(" | "));
        }
        out.push('\n');
        if let Some(note) = model_note(m.rows) {
            let _ = writeln!(out, "{note}\n");
        }
    }
    let _ = writeln!(out, "{PROPERTIES}\n");
    let _ = writeln!(out, "{TEST_PLAN}\n");
    let sizes: Vec<String> = MACHINES
        .iter()
        .map(|m| format!("{} {}", m.key, m.rows.len()))
        .collect();
    let total: usize = MACHINES.iter().map(|m| m.rows.len()).sum();
    let _ = writeln!(
        out,
        "**Size:** {}: **{total} rows** in total (revision 8: 137).\n",
        sizes.join(", ")
    );
    out.push_str(END);
    out
}
